import{_ as t,o as a,c as i,a2 as r}from"./chunks/framework.BjkiRu3Q.js";const f=JSON.parse('{"title":"First reservation: quote to settlement","description":"","frontmatter":{},"headers":[],"relativePath":"getting-started/first-reservation.md","filePath":"getting-started/first-reservation.md"}'),n={name:"getting-started/first-reservation.md"};function s(o,e,l,c,d,u){return a(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="first-reservation-quote-to-settlement" tabindex="-1">First reservation: quote to settlement <a class="header-anchor" href="#first-reservation-quote-to-settlement" aria-label="Permalink to &quot;First reservation: quote to settlement&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">Reference release</p><p>Operational guidance reviewed against v0.7.26. Verify the installed release, permissions and approved scope. Training uses authorized synthetic data; this guide does not authorize commercial activation.</p></div><h2 id="training-scenario" tabindex="-1">Training scenario <a class="header-anchor" href="#training-scenario" aria-label="Permalink to &quot;Training scenario&quot;">​</a></h2><p>Use an authorized synthetic tenant with configured locations, vehicle class, tariff, driver and vehicle. Choose a future pickup time within the test schedule. No real passenger contact, external messages or online charges are required.</p><ol><li>Create a one-way operator reservation. Select the market, valid pickup/drop-off, service date/time, passenger count, luggage and class. Enter a synthetic name and permitted telephone; leave email blank if not supplied.</li><li>Review the server quotation. If a valid tariff is unavailable, use manual quotation review. Do not invent a fare, discount or passenger email. Confirm required fields and submit once.</li><li>Verify the resulting reference, status and price. For an uncertain response, search for the reservation before retrying.</li><li>Dispatch only after the required quotation and booking checks. Select a suitable available driver and vehicle. Verify the full interval, conflicts, capacity and saved assignment.</li><li>Sign in with an authorized synthetic chauffeur account. Review and advance only the assigned journey through permitted milestones. Do not use a simulated administrator role as proof of chauffeur access.</li><li>If testing cash settlement, enter only the synthetic receipt amount. Review remaining balance, collecting driver and separate office handover. No real payment is made.</li><li>Review final reservation status, CRM linkage, payment ledger and audit evidence. Test notifications using previews or isolated authorized test channels only.</li></ol><p>Repeat with an independently assigned return leg, then test hourly or private tour workflows if offered. A completed training scenario is not authorization for real business.</p><p>See <a href="/plus/create-reservation.html">Create reservation</a>, <a href="/plus/dispatch-schedule.html">Dispatch</a>, <a href="/plus/cash-management.html">Cash management</a> and <a href="/plus/customer-booking-gateway.html">Customer gateway</a>.</p>',7)])])}const p=t(n,[["render",s]]);export{f as __pageData,p as default};
